#include <iostream>
using namespace std;

struct Rectangle {
    double length;
    double width;
};

int main() {
    Rectangle r1, r2;
    cout << "Enter length and width: ";
    cin >> r1.length >> r1.width;
    r2 = r1;
    r2.length = r2.length * 2;
    double a1 = r1.length * r1.width;
    double a2 = r2.length * r2.width;
    cout << "Area 1 = " << a1 << ", Area 2 = " << a2 << endl;
    if (a1 > a2) cout << "Rectangle 1 is bigger" << endl;
    else cout << "Rectangle 2 is bigger" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Date {
    int day;
    int month;
    int year;
};

struct Student {
    int id;
    string name;
    Date birth;
};

int main() {
    Student a = {1, "Ali", {5, 3, 2005}};
    Student b = {1, "Ali", {5, 3, 2005}};
    b.birth.year = 2006;
    if (a.id == b.id && a.name == b.name &&
        a.birth.day == b.birth.day && a.birth.month == b.birth.month &&
        a.birth.year == b.birth.year) {
        cout << "Same record" << endl;
    } else {
        cout << "Different records" << endl;
    }
    cout << "a born in " << a.birth.year << ", b born in " << b.birth.year << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Result {
    string name;
    int marks[3];
    double average;
    char grade;
};

int main() {
    Result r;
    int total = 0;
    cin >> r.name;
    for (int i = 0; i < 3; i++) {
        cin >> r.marks[i];
        total += r.marks[i];
    }
    r.average = total / 3.0;
    if (r.average >= 85) r.grade = 'A';
    else if (r.average >= 70) r.grade = 'B';
    else if (r.average >= 50) r.grade = 'C';
    else r.grade = 'F';
    cout << r.name << " average " << r.average << " grade " << r.grade << endl;
    return 0;
}

